"""Read-only network, mining, mempool, and chain dashboard."""

DASHBOARD = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PowCoin Explorer</title>
<style>
:root{color-scheme:dark;--bg:#070b12;--panel:#101a28;--line:#27384b;--text:#e9f0f8;--muted:#91a3b8;--gold:#f6bd54;--green:#58d68c;--blue:#71bfff;--red:#ff8795}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#2a2112,transparent 29%),var(--bg);color:var(--text);font:14px/1.5 system-ui,sans-serif}
header{position:sticky;top:0;z-index:5;display:flex;justify-content:space-between;gap:12px;align-items:center;padding:15px max(20px,calc((100vw - 1200px)/2));border-bottom:1px solid var(--line);background:#070b12ee;backdrop-filter:blur(10px)}
.brand{font-size:18px;font-weight:900;letter-spacing:.08em}.brand span{color:var(--gold)}main{width:min(1200px,calc(100% - 28px));margin:25px auto 55px}h1{font-size:clamp(27px,4vw,42px);margin:0}h2{font-size:19px;margin:0}.muted{color:var(--muted)}.mono,code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.hero{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:18px}.hero p{margin:4px 0 0}.refresh{padding:9px 13px;border:1px solid #745825;border-radius:8px;background:#332710;color:#ffe6ad;font-weight:700;cursor:pointer}
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;margin-bottom:18px}.card{border:1px solid var(--line);border-radius:13px;background:linear-gradient(145deg,#111c2c,#0b131f);box-shadow:0 14px 35px #0004}.stat{padding:16px}.stat span,.metric span{display:block;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em}.stat b{display:block;margin-top:5px;font:700 22px ui-monospace,monospace}.stat small{display:block;margin-top:4px;color:var(--muted);font-size:11px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}.section{padding:18px;min-width:0}.section-head{display:flex;justify-content:space-between;gap:12px;align-items:baseline;margin-bottom:14px}.section-head p{margin:0;color:var(--muted);font-size:12px}.badge{display:inline-block;border-radius:99px;padding:3px 8px;background:#143422;color:var(--green);font-size:11px;font-weight:700}.badge.off{background:#36202a;color:var(--red)}.badge.neutral{background:#203043;color:var(--blue)}
.miner-list,.transfer-list,.block-list{display:grid;gap:9px}.miner,.transfer,.block{border:1px solid var(--line);border-radius:9px;background:#0a121e;padding:12px}.miner-top,.transfer-top{display:flex;justify-content:space-between;align-items:center;gap:9px}.miner-name,.transfer-title{font-weight:700}.miner-address,.transfer-address,.hash{overflow-wrap:anywhere;color:var(--blue);font:12px ui-monospace,monospace}.miner-address{margin-top:7px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:11px}.metric{border-radius:7px;background:#0e1d2d;padding:8px;min-width:0}.metric b{display:block;margin-top:3px;font:700 13px ui-monospace,monospace;overflow-wrap:anywhere}.help{margin:12px 0 0;color:var(--muted);font-size:12px}.empty{padding:18px;border-radius:9px;background:#0a121e;color:var(--muted)}.error{color:var(--red)}
.transfer-top{margin-bottom:7px}.transfer-address{display:grid;gap:3px}.transfer-values{display:flex;flex-wrap:wrap;gap:7px 16px;margin-top:9px;color:var(--muted);font-size:12px}.transfer-values strong{color:var(--text)}.tabs{display:flex;gap:7px;margin-bottom:12px}.tabs button{padding:6px 10px;border:1px solid var(--line);border-radius:7px;background:#0b1622;color:var(--muted);cursor:pointer}.tabs button.active{border-color:#3875a1;color:var(--blue);background:#13263a}.search{display:flex;gap:9px;margin-bottom:13px}.search input{flex:1;min-width:0;padding:10px;border:1px solid var(--line);border-radius:8px;background:#080f18;color:var(--text)}.search button{padding:10px 14px;border:1px solid #285e82;border-radius:8px;background:#102d43;color:#d8efff;font-weight:700;cursor:pointer}.wallet-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0}.wallet-summary .metric b{font-size:14px}.history{display:grid;gap:6px}.history-row{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px;padding:9px;border:1px solid var(--line);border-radius:7px;font-size:12px}.block{padding:0}.block summary{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px;cursor:pointer}.block-body{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:12px;border-top:1px solid var(--line)}.field{min-width:0}.field span{display:block;color:var(--muted);font-size:11px;text-transform:uppercase}.field code{display:block;overflow-wrap:anywhere}.block-txs{grid-column:1/-1}.foot{margin-top:16px;text-align:center;color:var(--muted);font-size:12px}
@media(max-width:800px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}}@media(max-width:520px){.hero{align-items:start;flex-direction:column}.stats{grid-template-columns:1fr 1fr}.stat b{font-size:17px}.metrics{grid-template-columns:1fr 1fr}.wallet-summary{grid-template-columns:1fr}.block-body{grid-template-columns:1fr}}
</style></head><body>
<header><div class="brand"><span>POW</span>COIN EXPLORER</div><div id="connection" class="badge off">CONNECTING</div></header>
<main><div class="hero"><div><h1>Node overview</h1><p class="muted">Mining, pending transfers, and the chain as seen by this full node.</p></div><button id="refresh" class="refresh">Refresh now</button></div>
<div class="stats"><div class="card stat"><span>Chain height</span><b id="height">—</b></div><div class="card stat"><span>Available nodes</span><b id="available-nodes">—</b><small>This node and reachable peers</small></div><div class="card stat"><span>Currency</span><b id="currency">—</b></div><div class="card stat"><span>Pending transfers</span><b id="pending">—</b></div><div class="card stat"><span>Configured difficulty</span><b id="difficulty">—</b><small id="difficulty-tries">Expected tries per block</small></div><div class="card stat"><span>Cumulative work</span><b id="work">—</b></div></div>
<div class="grid"><section class="card section"><div class="section-head"><h2>Mining nodes</h2><p id="miner-updated">Waiting for status</p></div><div id="miners" class="miner-list"><div class="empty">Loading miners…</div></div><p class="help">Hash attempts are current-candidate tries, not a percent complete. A valid hash can appear on any try. Peer figures are reported by those peers.</p></section>
<section class="card section"><div class="section-head"><h2>Transfers</h2><p id="transfer-count">Waiting for mempool</p></div><div class="tabs"><button id="tab-pending" class="active">Pending</button><button id="tab-confirmed">Recent confirmed</button></div><div id="transfers" class="transfer-list"><div class="empty">Loading transfers…</div></div></section></div>
<div class="grid"><section class="card section"><div class="section-head"><h2>Address history</h2><p>Public address only</p></div><div class="search"><input id="wallet-address" maxlength="64" spellcheck="false" placeholder="Enter 64-character address"><button id="wallet-search">View</button></div><div id="wallet-result"></div></section>
<section class="card section"><div class="section-head"><h2>How to read this</h2></div><p class="muted">Pending means this node has validated a signed transfer but no block on its current chain contains it. A transfer in the latest block has 1 confirmation; each later block adds one. A chain reorganization can change that count.</p><p class="muted">Configured difficulty is fixed for this network. At N bits, a miner needs about 2<sup>N</sup> hash attempts on average per block. Actual attempts vary.</p><p class="muted">Mining is optional. The reward address is public; no private wallet key is held by the node.</p></section></div>
<section class="card section"><div class="section-head"><h2>Canonical blocks</h2><p id="updated">Loading…</p></div><div id="blocks" class="block-list"><div class="empty">Loading blocks…</div></div></section><div class="foot">Read-only explorer · updates every 5 seconds</div></main>
<script>
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=value=>value?`${String(value).slice(0,12)}…${String(value).slice(-8)}`:'—';
const coins=value=>(Number(value)/100000000).toFixed(8);
const fmt=value=>Number(value||0).toLocaleString();
const date=value=>value?new Date(value*1000).toLocaleString():'Genesis';
let blocks=[],pending=[],tab='pending',address='';
async function get(path){const response=await fetch(path,{cache:'no-store'});if(!response.ok)throw Error(`HTTP ${response.status}`);return response.json()}
function minerCard(name,online,mining,address,progress,peerHeight){const badge=!online?'<span class="badge off">OFFLINE</span>':mining?'<span class="badge">MINING</span>':'<span class="badge neutral">VALIDATING</span>';const detail=!online?'Last known state unavailable':mining?`Reward address: <span class="miner-address">${esc(address||'Unknown')}</span>`:'No active miner on this node';return `<article class="miner"><div class="miner-top"><span class="miner-name">${esc(name)}</span>${badge}</div><div class="muted" style="margin-top:6px">${detail}</div><div class="metrics"><div class="metric"><span>Chain height</span><b>${peerHeight??'—'}</b></div><div class="metric"><span>Candidate</span><b>${online&&mining?(progress?.candidate_height??'—'):'—'}</b></div><div class="metric"><span>Hash rate</span><b>${online&&mining&&progress?.hash_rate!=null?fmt(progress.hash_rate)+' H/s':'—'}</b></div><div class="metric"><span>Tries on candidate</span><b>${online&&mining&&progress?.attempts!=null?fmt(progress.attempts):'—'}</b></div><div class="metric"><span>Last mined block</span><b>${online&&mining?(progress?.last_block_height??'—'):'—'}</b></div></div></article>`}
function renderMiners(status){const local=status.mining_progress||{},peers=status.peer_status||[];let html=minerCard('This node',true,!!status.mining,local.reward_address,local,status.height);for(const peer of peers){html+=minerCard(peer.url,peer.reachable,peer.mining,peer.reward_address,{hash_rate:peer.hash_rate},peer.height)}$('miners').innerHTML=html;$('available-nodes').textContent=1+peers.filter(peer=>peer.reachable).length;$('miner-updated').textContent=`${peers.length} configured peers`}
function transferCard(tx,txid,confirmations,height){return `<article class="transfer"><div class="transfer-top"><span class="transfer-title">${height?'Block #'+height:'Pending transfer'}</span><span class="badge ${height?'':'neutral'}">${confirmations} confirmation${confirmations===1?'':'s'}</span></div><div class="transfer-address">From ${esc(short(tx.sender))} → To ${esc(short(tx.recipient))}</div><div class="transfer-values"><span>Amount <strong>${coins(tx.amount)} PWN</strong></span><span>Fee <strong>${coins(tx.fee)} PWN</strong></span><span>Nonce <strong>${esc(tx.nonce)}</strong></span></div>${txid?`<div class="muted mono" style="font-size:11px;margin-top:8px;overflow-wrap:anywhere">TX ${esc(txid)}</div>`:''}</article>`}
function renderTransfers(height){const recent=[];for(const block of [...blocks].reverse()){for(const tx of [...(block.transactions||[])].reverse()){recent.push({tx,height:block.height});if(recent.length>=12)break}if(recent.length>=12)break}const items=tab==='pending'?pending:recent;$('transfer-count').textContent=`${pending.length} pending · ${recent.length} recent confirmed`;$('transfers').innerHTML=items.length?items.map(item=>transferCard(item.transaction||item.tx,item.txid,item.confirmations??(height-item.height+1),item.height)).join(''):`<div class="empty">${tab==='pending'?'No pending transfers on this node.':'No confirmed transfers yet.'}</div>`;$('tab-pending').classList.toggle('active',tab==='pending');$('tab-confirmed').classList.toggle('active',tab==='confirmed')}
function renderBlocks(height){const opened=new Set([...document.querySelectorAll('#blocks details[open]')].map(el=>el.dataset.hash));$('blocks').innerHTML=[...blocks].reverse().slice(0,40).map(block=>`<details class="block" data-hash="${esc(block.hash)}" ${opened.has(block.hash)?'open':''}><summary><strong>#${block.height}</strong><span class="hash">${esc(short(block.hash))}</span><span class="muted">${block.height?height-block.height+1:0} conf · ${(block.transactions||[]).length} tx</span></summary><div class="block-body"><div class="field"><span>Hash</span><code>${esc(block.hash)}</code></div><div class="field"><span>Previous</span><code>${esc(block.previous||'—')}</code></div><div class="field"><span>Time</span><code>${esc(date(block.timestamp))}</code></div><div class="field"><span>Miner reward address</span><code>${esc(block.miner||'Genesis')}</code></div><div class="field"><span>Reward</span><code>${coins(block.reward||0)} PWN</code></div><div class="field"><span>Nonce</span><code>${block.nonce??'—'}</code></div><div class="field"><span>Merkle root</span><code>${esc(block.merkle||'—')}</code></div><div class="block-txs">${(block.transactions||[]).map(tx=>transferCard(tx,null,height-block.height+1,block.height)).join('')||'<div class="empty">No transfers in this block.</div>'}</div></div></details>`).join('')||'<div class="empty">No blocks found.</div>'}
function renderHistory(){if(!address)return;const rows=[];for(const block of blocks){if(block.height&&block.miner===address)rows.push({type:'MINED',other:'Block reward',amount:block.reward,height:block.height});for(const tx of block.transactions||[]){if(tx.sender===address)rows.push({type:'SENT',other:'To '+short(tx.recipient),amount:-tx.amount-tx.fee,height:block.height});if(tx.recipient===address)rows.push({type:'RECEIVED',other:'From '+short(tx.sender),amount:tx.amount,height:block.height})}}get('/accounts/'+address).then(account=>{$('wallet-result').innerHTML=`<div class="wallet-summary"><div class="metric"><span>Spendable</span><b>${coins(account.balance)} PWN</b></div><div class="metric"><span>Immature rewards</span><b>${coins(account.immature)} PWN</b></div><div class="metric"><span>History entries</span><b>${rows.length}</b></div></div><div class="history">${rows.reverse().map(r=>`<div class="history-row"><b>${r.type} · Block #${r.height}</b><span>${esc(r.other)}</span><span>${r.amount>=0?'+':''}${coins(r.amount)} PWN</span></div>`).join('')||'<div class="empty">No confirmed history for this address.</div>'}</div>`}).catch(e=>{$('wallet-result').innerHTML=`<div class="error">${esc(e.message)}</div>`})}
async function load(){try{const status=await get('/status');const [pool,chain]=await Promise.all([get('/mempool/details'),loadBlocks(status)]);pending=pool;blocks=chain;$('height').textContent=status.height;$('currency').textContent=`${status.name} (${status.symbol})`;$('pending').textContent=status.pending;$('difficulty').textContent=`${status.pow_bits} bits`;$('difficulty-tries').textContent=`≈ ${fmt(2**status.pow_bits)} tries per block`;$('work').textContent=fmt(status.work);renderMiners(status);renderTransfers(status.height);renderBlocks(status.height);renderHistory();$('updated').textContent=`Updated ${new Date().toLocaleTimeString()} · latest 40 shown`;$('connection').textContent='NODE ONLINE';$('connection').className='badge'}catch(e){$('connection').textContent='NODE ERROR';$('connection').className='badge off';$('updated').textContent=e.message;$('miners').innerHTML=`<div class="error">Unable to refresh: ${esc(e.message)}</div>`}}
async function loadBlocks(status){if(blocks.length&&status.height===blocks.length-1&&status.tip===blocks.at(-1).hash)return blocks;if(blocks.length&&status.height>=blocks.length-1){const start=blocks.length-1;const first=await get(`/blocks?start=${start}&count=${Math.min(50,status.height+1-start)}`);if(first.blocks[0]?.hash===blocks.at(-1).hash){const result=blocks.slice(0,-1).concat(first.blocks);for(let next=result.length;next<=status.height;next+=50){const page=await get(`/blocks?start=${next}&count=${Math.min(50,status.height+1-next)}`);result.push(...page.blocks)}if(result.at(-1)?.hash===status.tip)return result}}const result=[];for(let start=0;start<=status.height;start+=50){const page=await get(`/blocks?start=${start}&count=${Math.min(50,status.height+1-start)}`);result.push(...page.blocks)}if(result.at(-1)?.hash!==status.tip)throw Error('Chain changed during refresh; retrying');return result}
$('refresh').onclick=load;$('tab-pending').onclick=()=>{tab='pending';renderTransfers(blocks.at(-1)?.height||0)};$('tab-confirmed').onclick=()=>{tab='confirmed';renderTransfers(blocks.at(-1)?.height||0)};$('wallet-search').onclick=()=>{const value=$('wallet-address').value.trim().toLowerCase();if(!/^[0-9a-f]{64}$/.test(value)){$('wallet-result').innerHTML='<div class="error">Enter a valid 64-character hexadecimal address.</div>';return}address=value;renderHistory()};$('wallet-address').onkeydown=e=>{if(e.key==='Enter')$('wallet-search').click()};load();setInterval(load,5000);
</script></body></html>'''
